using namespace System.Net

# $sub and $DID are injected by CloudLabs. Learner/service-generated state is checked after deployment.
$rg=(Get-AzResource -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'asclab*' } | Select-Object -First 1).ResourceGroupName; if(-not $rg){ throw 'Could not locate the lab resource group: no resource named asclab* found in the subscription.' };$automationName='war-contoso-high-severity-recommendations';$logicAppName='la-contoso-defender-recommendations';$count=0;$found=$false;$last='No validation attempt completed.'
function T($o,$n){if($null-eq $o){return ''};$p=$o.PSObject.Properties[$n];if($null-eq $p -or $null-eq $p.Value){return ''};[string]$p.Value}
function Reply($s,$m){if($s-eq 'Succeeded'){$body=@{Status = "Succeeded";Message = $m}|ConvertTo-Json -Depth 12 -Compress}else{$body=@{Status = "Failed";Message = $m}|ConvertTo-Json -Depth 12 -Compress};Push-OutputBinding -Name Response -Value ([HttpResponseContext]@{StatusCode=[HttpStatusCode]::OK;Body=$body}) -Clobber}
function J($id,$v){$r=Invoke-AzRestMethod -Path "$id`?api-version=$v" -Method GET -ErrorAction Stop;if([string]::IsNullOrWhiteSpace($r.Content)){throw "Azure returned empty content for '$id'."};$r.Content|ConvertFrom-Json -Depth 100}
do{$count++;try{Set-AzContext -Subscription $sub -ErrorAction Stop|Out-Null;$rs=@(Get-AzResource -ResourceGroupName $rg -ExpandProperties -ErrorAction Stop);$a=@($rs|Where-Object{$_.Name-eq $automationName -and $_.ResourceType-match 'Microsoft.Security/automations'}|Select-Object -First 1);if($null-eq $a){throw "Workflow automation '$automationName' is not visible."};$ap=(J $a.ResourceId '2019-01-01-preview').properties;if([bool]$ap.isEnabled-ne $true){throw "Workflow automation '$automationName' is disabled."};$src=@($ap.sources);if($src.Count-ne 1 -or (T $src[0] 'eventSource')-ne 'Assessments'){throw 'Automation must have one Assessments source and no Alerts source.'};$rules=@($src[0].ruleSets|ForEach-Object{@($_.rules)});if(@($rules|Where-Object{(T $_ 'propertyJPath')-eq '$.severity' -and (T $_ 'operator')-eq 'Equals' -and (T $_ 'expectedValue')-eq 'High'}).Count-eq 0){throw 'Automation has no High-severity recommendation rule.'};$acts=@($ap.actions);$la=@($rs|Where-Object{$_.Name-eq $logicAppName -and $_.ResourceType-match 'Microsoft.Logic/workflows'}|Select-Object -First 1);if($acts.Count-ne 1 -or (T $acts[0] 'actionType')-ne 'LogicApp' -or $null-eq $la){throw 'Automation must target the named Logic App.'};if((T $acts[0] 'logicAppResourceId').ToLowerInvariant() -ne $la.ResourceId.ToLowerInvariant()){throw 'Automation target does not match the named Logic App.'};$def=$la.Properties.definition;if($null-eq $def){$def=(J $la.ResourceId '2019-05-01').properties.definition};$tr=@($def.triggers.PSObject.Properties);$tj=$tr[0].Value|ConvertTo-Json -Depth 100 -Compress;if($tr.Count-ne 1 -or $tj-notmatch '(?i)recommendation' -or $tj-notmatch '(?i)Microsoft Defender for Cloud|securitycenter|defender'){throw 'Logic App lacks the supported Defender recommendation trigger.'};$wa=@($def.actions.PSObject.Properties);if($wa.Count-ne 1 -or $wa[0].Name-ne 'Compose' -or (T $wa[0].Value 'type')-ne 'Compose' -or $null-eq $wa[0].Value.inputs){throw 'Logic App must contain only Compose with payload input.'};$q="securityresources | where subscriptionId == '$sub' | project id,name,properties";$sr=@(Search-AzGraph -Query $q -Subscription $sub -First 5000 -ErrorAction Stop);$healthy=@($sr|Where-Object{$j=$_.properties|ConvertTo-Json -Depth 50;$j-match '(?i)attack.?path' -and $j-match '(?i)healthy'});if($healthy.Count-eq 0){throw 'No healthy attack-path recommendation evidence was returned. Attack path analysis is produced by the cloud security graph after agentless scanning completes.'};$found=$true;Reply 'Succeeded' "Automation '$automationName' is enabled, recommendation-only, High severity, and targets '$logicAppName'; the Logic App has the Defender recommendation trigger and only Compose; healthy attack-path recommendation evidence is present."}catch{$last="Attempt $count of 3: $($_.Exception.Message)";Reply 'Failed' $last;if($count-lt 3){Start-Sleep -Seconds 10}}}while($count-lt 3 -and -not $found)
if(-not $found){Reply 'Failed' "Challenge 6 failed after 3 attempts in '$rg'. Last actionable reason: $last"}